<?php require_once __DIR__.'/document_studio_common.php';$u=uid();try{$action=$_GET['action']??'';
if($action==='list'){$pid=trim((string)($_GET['project_id']??''));project($pdo,$pid);$q=$pdo->prepare("SELECT d.id,d.requirement_key,d.requirement_type,d.document_type_id,d.title,d.status,d.priority,d.relevance,d.review_status,COALESCE(t.is_chapter,0)is_chapter FROM requirement_documents d LEFT JOIN document_types t ON t.id=d.document_type_id WHERE d.project_id=? ORDER BY d.sort_order,d.requirement_key");$q->execute([$pid]);$rows=$q->fetchAll(PDO::FETCH_ASSOC);$l=$pdo->prepare("SELECT source_document_id parent_id,target_document_id child_id FROM requirement_document_links WHERE project_id=? AND link_type='parent_of'");$l->execute([$pid]);$parents=[];foreach($l->fetchAll(PDO::FETCH_ASSOC)as$x)$parents[$x['child_id']][]=$x['parent_id'];foreach($rows as&$r)$r['parent_ids']=$parents[$r['id']]??[];out(['success'=>true,'documents'=>$rows]);}
if($action==='get'){$id=trim((string)($_GET['id']??''));$d=doc($pdo,$id);$d['metadata']=json_decode($d['metadata']??'{}',true)?:[];$q=$pdo->prepare('SELECT id,editor_block_id,block_type,content FROM requirement_document_blocks WHERE document_id=? ORDER BY sort_order,id');$q->execute([$id]);$blocks=[];foreach($q->fetchAll(PDO::FETCH_ASSOC)as$r){$data=json_decode($r['content'],true)?:[];$data['_recordId']=$r['id'];$b=['type'=>$r['block_type'],'data'=>$data];if($r['editor_block_id'])$b['id']=$r['editor_block_id'];$blocks[]=$b;}out(['success'=>true,'document'=>$d,'editor'=>['time'=>(int)(microtime(true)*1000),'blocks'=>$blocks,'version'=>'2.31.0']]);}
if($action==='create'&&$_SERVER['REQUEST_METHOD']==='POST'){$x=body();$pid=trim((string)($x['project_id']??''));project($pdo,$pid);$typeId=trim((string)($x['document_type_id']??''));$q=$pdo->prepare('SELECT * FROM document_types WHERE id=? AND is_active=1 AND(project_id IS NULL OR project_id=?)');$q->execute([$typeId,$pid]);$t=$q->fetch(PDO::FETCH_ASSOC);if(!$t)out(['success'=>false,'error'=>'Dokumenttyp nicht gefunden.'],404);$title=trim((string)($x['title']??''));if($title==='')out(['success'=>false,'error'=>'Titel fehlt.'],422);$key=$t['type_key'];$pdo->beginTransaction();$pdo->prepare('INSERT INTO requirement_document_sequences(project_id,requirement_type,last_number)VALUES(?,?,1)ON DUPLICATE KEY UPDATE last_number=last_number+1')->execute([$pid,$key]);$n=$pdo->prepare('SELECT last_number FROM requirement_document_sequences WHERE project_id=? AND requirement_type=? FOR UPDATE');$n->execute([$pid,$key]);$num=(int)$n->fetchColumn();$display=str_replace(['{TYPE}','{NUMBER:3}','{NUMBER:4}','{NUMBER}'],[$key,str_pad((string)$num,3,'0',STR_PAD_LEFT),str_pad((string)$num,4,'0',STR_PAD_LEFT),(string)$num],$t['number_pattern']);$id=uuid4();$pdo->prepare('INSERT INTO requirement_documents(id,project_id,document_type_id,requirement_key,requirement_type,title,status,priority,relevance,review_status,metadata,created_by,updated_by)VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$id,$pid,$typeId,$display,$key,$title,'Open','Medium','Must','New','{}',$u,$u]);$blocks=is_array($x['blocks']??null)?$x['blocks']:[];$ins=$pdo->prepare('INSERT INTO requirement_document_blocks(id,document_id,block_type,content,sort_order)VALUES(?,?,?,?,?)');foreach(array_values($blocks)as$i=>$b)$ins->execute([uuid4(),$id,(string)($b['type']??'text'),json_encode($b['data']??[],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$i]);$pdo->commit();out(['success'=>true,'id'=>$id,'key'=>$display],201);}
if($action==='save'&&$_SERVER['REQUEST_METHOD']==='POST'){$x=body();$id=trim((string)($x['id']??''));$blocks=$x['blocks']??null;if(!is_array($blocks))out(['success'=>false,'error'=>'Blöcke fehlen.'],422);$pdo->beginTransaction();doc($pdo,$id);$pdo->prepare('UPDATE requirement_documents SET title=?,status=?,priority=?,relevance=?,review_status=?,metadata=?,updated_by=? WHERE id=?')->execute([trim((string)($x['title']??'')),trim((string)($x['status']??'Open')),trim((string)($x['priority']??'Medium')),trim((string)($x['relevance']??'Must')),trim((string)($x['review_status']??'New')),json_encode($x['metadata']??[],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$u,$id]);$o=$pdo->prepare('SELECT id FROM requirement_document_blocks WHERE document_id=?');$o->execute([$id]);$known=array_fill_keys($o->fetchAll(PDO::FETCH_COLUMN),1);$keep=[];$ins=$pdo->prepare('INSERT INTO requirement_document_blocks(id,document_id,editor_block_id,block_type,content,sort_order)VALUES(?,?,?,?,?,?)');$upd=$pdo->prepare('UPDATE requirement_document_blocks SET editor_block_id=?,block_type=?,content=?,sort_order=? WHERE id=? AND document_id=?');foreach(array_values($blocks)as$i=>$b){$data=$b['data']??[];$rid=trim((string)($data['_recordId']??''));unset($data['_recordId']);$json=json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$eid=$b['id']??null;$type=$b['type']??'text';if(isset($known[$rid])){$upd->execute([$eid,$type,$json,$i,$rid,$id]);$keep[]=$rid;}else{$rid=uuid4();$ins->execute([$rid,$id,$eid,$type,$json,$i]);$keep[]=$rid;}}if($keep){$m=implode(',',array_fill(0,count($keep),'?'));$pdo->prepare("DELETE FROM requirement_document_blocks WHERE document_id=? AND id NOT IN($m)")->execute(array_merge([$id],$keep));}else$pdo->prepare('DELETE FROM requirement_document_blocks WHERE document_id=?')->execute([$id]);$pdo->commit();out(['success'=>true]);}out(['success'=>false,'error'=>'Unbekannte Aktion.'],400);
}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();out(['success'=>false,'error'=>$e->getMessage()],500);}